import sys

def findHeight(N, arr):
    if N == 0:
        return 0

    depth = [0] * N
    root = -1

    # Identify root
    for i in range(N):
        if arr[i] == -1:
            root = i
            break

    if root == -1:
        return 0

    # Calculate depth for each node by traversing up to root
    for i in range(N):
        if i == root:
            depth[i] = 0
            continue

        current = i
        count = 0
        while current != -1 and current != root:
            count += 1
            current = arr[current]

        # If we reached root, add 1 for the edge from root to child
        if current == root:
            depth[i] = count + 1
        else:
            # This case shouldn't happen in a valid tree but handle safely
            depth[i] = count

    return max(depth)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        arr = []
        for _ in range(N):
            arr.append(int(next(iterator)))

        result = findHeight(N, arr)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
